import{f as e,o,c as r,a2 as t}from"./chunks/framework.Cd9rfTEn.js";const g=JSON.parse('{"title":"Relevamiento funcional de Procoop (base DEMO)","description":"","frontmatter":{},"headers":[],"relativePath":"relevamiento/README.md","filePath":"relevamiento/README.md","lastUpdated":null}'),s={name:"relevamiento/README.md"};function i(d,a,n,c,l,u){return o(),r("div",null,[...a[0]||(a[0]=[t(`<h1 id="relevamiento-funcional-de-procoop-base-demo" tabindex="-1">Relevamiento funcional de Procoop (base DEMO) <a class="header-anchor" href="#relevamiento-funcional-de-procoop-base-demo" aria-label="Permalink to &quot;Relevamiento funcional de Procoop (base DEMO)&quot;">​</a></h1><p>Relevamiento hecho navegando Procoop <strong>en modo solo lectura</strong> por Escritorio Remoto de Chrome (PC <code>demo_pc</code>), el 3/11/2026.</p><ul><li><strong>Versión:</strong> Procoop 10.4.6.722, fecha de versión 03/08/2026.</li><li><strong>Instalación:</strong> &quot;Cooperativa eléctrica Laguna Larga Ltda.&quot; sobre la base DEMO.</li><li><strong>Sesión:</strong> usuario <code>COOPERATIVA</code>, alias <code>COOPONLINE</code>, punto de venta 0097.</li></ul><p>No se grabó, autorizó ni procesó nada: todas las ventanas se cerraron con Cancelar o Salir.</p><blockquote><p><strong>Atención con datos personales:</strong> la base DEMO contiene nombres, CUIT, domicilios y deudas que parecen reales. Las capturas en <code>capturas/</code> <strong>no deben subirse al repositorio ni compartirse fuera del equipo</strong> sin anonimizarlas primero (ver la regla de los docs: los entornos de test nunca usan datos personales reales).</p></blockquote><h2 id="_1-estructura-general-de-la-aplicacion" tabindex="-1">1. Estructura general de la aplicación <a class="header-anchor" href="#_1-estructura-general-de-la-aplicacion" aria-label="Permalink to &quot;1. Estructura general de la aplicación&quot;">​</a></h2><p>La aplicación es WinForms (DevExpress) con una cinta (ribbon) de 9 pestañas, una por módulo. Cada pestaña agrupa sus funciones en grupos.</p><p>Al iniciar sesión aparece una alerta, &quot;Hay facturas electrónicas pendientes de autorizar!&quot;. Desde ahí se abre la grilla &quot;Comprobantes Pendientes de Autorizar&quot;, con las columnas NumeroCompleto, Fecha, Cliente, Documento y Procesando, y los botones Exportar, Imprimir y Salir. Captura: <a href="capturas/00-comprobantes-pendientes-autorizar.png">00</a>.</p><table tabindex="0"><thead><tr><th>Pestaña</th><th>Grupos y funciones</th><th>Captura</th></tr></thead><tbody><tr><td>Servicios a Titulares</td><td><strong>Titulares:</strong> Administración de Titulares, Administración de Personas, Consultas e Informes. <strong>Consumos:</strong> Registro de Lectura, Telemed, Opciones de consumos, Opciones de Telefonía, Informes de Consumos. <strong>Ventas y Facturación:</strong> Presupuestos, Venta de Productos, Facturación, Informes de Ventas y Facturación, Libro IVA Ventas, Movimiento de Conceptos. <strong>Cobranza:</strong> Apertura de Caja, Cobranza Local, Opciones de Cobranza, Informes de Cobranzas. <strong>Configuración.</strong></td><td><a href="capturas/01-menu-servicios-titulares.png">01</a></td></tr><tr><td>Crédito y Gestión de Mora</td><td><strong>Financiaciones:</strong> Emitir Plan de Financiación, Informes. <strong>Gestión de Mora:</strong> Generar Notificaciones (1ª instancia), Tratamiento de Notificaciones Generadas, Tratamiento de Morosos, Notificaciones, Causas de Baja, Instancias de Mora, Excepciones de Mora, Informes.</td><td><a href="capturas/02-menu-credito-mora.png">02</a></td></tr><tr><td>Operaciones</td><td><strong>Técnica:</strong> Factibilidades, Órdenes, Carga Rápida de Reclamos, Informes. <strong>Telemed:</strong> Administración, Informes, Configuración. <strong>Planes de Vivienda:</strong> Materiales, Construcción, Informes.</td><td><a href="capturas/03-menu-operaciones.png">03</a></td></tr><tr><td>Compras y Stock</td><td><strong>Gestión de Compras:</strong> Solicitudes de Aprovisionamiento, Solicitudes de Cotización, Órdenes de Compra, Remitos, Comprobantes de Proveedores, Pago a Proveedores, Retenciones. <strong>Stock:</strong> Movimientos, Trazabilidad, Operaciones Especiales, Bienes de Uso, Fabricación. <strong>RMA.</strong> <strong>Informes:</strong> Compras, Stock, Libro IVA Compras, Correspondencia.</td><td><a href="capturas/04-menu-compras-stock.png">04</a></td></tr><tr><td>Tesorería</td><td><strong>Bancos:</strong> Movimientos Bancarios, Cuentas Propias. <strong>Tesorería:</strong> Movimientos, Valores de Terceros, Cheques Propios, Cupones de Tarjetas, Retenciones Recibidas, Cajas para Pagos a Proveedores, Cierre de Cajas. <strong>Informes.</strong></td><td><a href="capturas/05-menu-tesoreria.png">05</a></td></tr><tr><td>Sueldos</td><td><strong>Administración:</strong> Empleados, Empresas, Recibos. <strong>Procesos:</strong> Liquidación Masiva, Simulador, Impuesto a las Ganancias. <strong>Configuración:</strong> Variables, Conceptos, Aplicar Aumentos. <strong>Informes:</strong> Informes de Sueldos, Libro sueldo digital (deshabilitado).</td><td><a href="capturas/06-menu-sueldos.png">06</a></td></tr><tr><td>Contabilidad</td><td><strong>Movimientos:</strong> Asientos, Consultar Mayor, Balance General / Sumas y Saldos. <strong>Otras operaciones:</strong> Asientos Automáticos, Herramientas. <strong>Informes:</strong> Contables, de Gestión.</td><td><a href="capturas/07-menu-contabilidad.png">07</a></td></tr><tr><td>Herramientas</td><td>Actividades (Seguimiento, Informe), SMS, Tablero de Control, Traslados (Viajes, Informes), Turnero (Box, Turnero, Selección de Turnos, Estadísticas), Mesa de Entradas (Administración, Incidentes, Informes).</td><td><a href="capturas/08-menu-herramientas.png">08</a></td></tr><tr><td>Configuración</td><td><strong>General:</strong> Usuarios, Perfiles, Auditoría de Logueo, Copia de Seguridad, Base de Datos (deshabilitado), Actualizar. <strong>Tablas y Parámetros:</strong> Tablas del sistema, Parámetros del Sistema, Parámetros Externos, Autorización de Operaciones. <strong>Procoop WEB:</strong> Requisitos y Trámites, Archivos en la Web, Operaciones. <strong>Reportes:</strong> Editor de Reportes, Informes Personalizados, Procesos Personalizados.</td><td><a href="capturas/09-menu-configuracion.png">09</a></td></tr></tbody></table><h2 id="_2-titulares-cuentas-y-servicios-modelo-de-datos-visible" tabindex="-1">2. Titulares, cuentas y servicios (modelo de datos visible) <a class="header-anchor" href="#_2-titulares-cuentas-y-servicios-modelo-de-datos-visible" aria-label="Permalink to &quot;2. Titulares, cuentas y servicios (modelo de datos visible)&quot;">​</a></h2><h3 id="administracion-de-titulares" tabindex="-1">Administración de Titulares <a class="header-anchor" href="#administracion-de-titulares" aria-label="Permalink to &quot;Administración de Titulares&quot;">​</a></h3><p>Captura: <a href="capturas/10-administracion-titulares.png">10</a> y <a href="capturas/11-titulares-listado.png">11</a>.</p><ul><li><strong>Filtros de búsqueda:</strong> Persona, Calle, Documento, Titular, rango Entre/y, Cuenta, &quot;Consultar Domicilio de Servicios&quot; y &quot;Solo cuentas con servicios activos&quot;. Para buscar hay que ingresar al menos un valor.</li><li><strong>Acciones:</strong> Agregar, Modificar, Baja, Consultar, Imprimir y Operación.</li><li><strong>Columnas de la grilla:</strong> Titular Nº, Nombre, Documento, NIP, Activo.</li></ul><h3 id="ficha-del-titular" tabindex="-1">Ficha del titular <a class="header-anchor" href="#ficha-del-titular" aria-label="Permalink to &quot;Ficha del titular&quot;">​</a></h3><p>Captura: <a href="capturas/12-titular-ficha.png">12</a> y <a href="capturas/13-titular-cuenta-servicios.png">13</a>. Se abre en modo &quot;Sólo LECTURA&quot; y tiene tres pestañas:</p><ul><li><strong>Datos Persona:</strong> datos de la persona física o jurídica.</li><li><strong>Titular:</strong> datos del titular.</li><li><strong>Cuentas y Servicios:</strong> la jerarquía de cuentas y servicios del titular.</li></ul><p>La jerarquía que se ve en la pestaña Cuentas y Servicios es:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Persona ──► Titular (N° titular, NIP)</span></span>
<span class="line"><span>              └── Cuenta (N°, domicilio, condición IVA: CONSUMIDOR FINAL / EXENTO…)</span></span>
<span class="line"><span>                    └── Grupo Factura (G.F.)</span></span>
<span class="line"><span>                          └── Servicio (tipo + id medidor + estado + categoría)</span></span>
<span class="line"><span>                                ej. ENERGIA ELECTRICA – 5884320 – conectado – ALUMBRADO PUBLICO</span></span>
<span class="line"><span>                                ej. GAS NATURAL – 9583371 – baja – SGP 1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>El panel derecho muestra los Trámites de la Cuenta, las Observaciones (Fecha, Título y Bloqueo) y las observaciones propias del servicio. Desde la ficha se puede acceder a Adjuntos, WhatsApp y email.</p><p><strong>Implicancia para GoodApps:</strong> una cooperativa es <strong>multiservicio</strong>: energía, gas, telefonía, agua y tasas pueden convivir en la misma cuenta. El &quot;Grupo Factura&quot; define qué servicios salen juntos en un mismo comprobante. Las observaciones tienen un flag de <strong>bloqueo</strong>, que probablemente impide operar sobre la cuenta.</p><h3 id="administracion-de-servicios-servicio-de-energia" tabindex="-1">Administración de Servicios (servicio de energía) <a class="header-anchor" href="#administracion-de-servicios-servicio-de-energia" aria-label="Permalink to &quot;Administración de Servicios (servicio de energía)&quot;">​</a></h3><p>Captura: <a href="capturas/14-cuenta-servicio-energia.png">14</a> y <a href="capturas/15-servicio-energia-detalle.png">15</a>.</p><table tabindex="0"><thead><tr><th>Bloque</th><th>Campos</th></tr></thead><tbody><tr><td>Cabecera</td><td>ID Servicio, Servicio (1 ENERGÍA ELÉCTRICA), Clase (ej. 4 TASA HOSPITAL MUNICIPAL)</td></tr><tr><td>Ubicación</td><td>Domicilio, Referencia, Catastro (Cod/Sec/Man/Par/PH/Lote), DD JJ, Contrato, Inmueble, GIS</td></tr><tr><td>Servicio</td><td>Categoría tarifaria (ej. 19 ALUMBRADO PÚBLICO), Actividad, Observaciones, Garante, Grupo Factura, fechas de Alta/Baja</td></tr><tr><td>Generalidades</td><td>Estado (CONECTADO) y fecha del último estado</td></tr><tr><td>Medidor</td><td>Modelo (Galileo), Id medidor, Obs., Unidades bonificadas, Dígitos, Factor de multiplicación, HP, Testigo, Tipo (MONOFÁSICO)</td></tr><tr><td>Flags</td><td>Lectura con factor de multiplicación, No aplica recategorización, Alta desde CoopOnline, No Facturar, Provisorio / Cobrar provisorio</td></tr><tr><td>Otros</td><td>Profesional (instalador), Certificado Nro/Vto, Id Cliente, Fecha Vto</td></tr><tr><td>Demanda</td><td>Demanda Pico / Fuera de Pico (para tarifas con potencia contratada)</td></tr><tr><td>Lectura</td><td>Zona, Sector, Recorrido (definen la ruta del lecturista)</td></tr><tr><td>Varios</td><td>Última facturación (período), Id Factibilidad, Matrícula, Latitud/Longitud</td></tr></tbody></table><h2 id="_3-consumos-registro-manual-de-lecturas" tabindex="-1">3. Consumos: Registro manual de Lecturas <a class="header-anchor" href="#_3-consumos-registro-manual-de-lecturas" aria-label="Permalink to &quot;3. Consumos: Registro manual de Lecturas&quot;">​</a></h2><p>Captura: <a href="capturas/19-registro-lectura.png">19</a>.</p><ul><li><strong>Encabezado:</strong> Fecha, Período (mes + año), Servicio, Titular, Cuenta, Observación, check &quot;Consumo Estimado&quot; y botón &quot;Consulta de consumos&quot;.</li><li><strong>Grilla de carga:</strong> Servicio, Fecha Anterior, Lectura Anterior, Consumo Anterior, Lectura Actual, Consumo Actual, Tipo de Energía, Concepto. El botón <strong>&quot;Correcto&quot;</strong> confirma la lectura.</li><li><strong>Datos adicionales del servicio:</strong> Categoría, Característica, Nº Medidor, Dígitos, Domicilio, Factor Multiplicación, Cos. Fi (factor de potencia) e Indicado.</li><li><strong>Grilla de consumos anteriores:</strong> Categoría, Medidor, Fecha y Lectura anterior, Fecha y Lectura actual, Días, Consumo, Período, Factura.</li></ul><p>La carga masiva de lecturas entra por <strong>Telemed</strong>: medición remota o lectores portátiles.</p><h2 id="_4-facturacion-administracion-de-comprobantes" tabindex="-1">4. Facturación: Administración de Comprobantes <a class="header-anchor" href="#_4-facturacion-administracion-de-comprobantes" aria-label="Permalink to &quot;4. Facturación: Administración de Comprobantes&quot;">​</a></h2><h3 id="listado" tabindex="-1">Listado <a class="header-anchor" href="#listado" aria-label="Permalink to &quot;Listado&quot;">​</a></h3><p>Captura: <a href="capturas/16-facturacion.png">16</a> y <a href="capturas/17-comprobantes-listado.png">17</a>.</p><ul><li><strong>Navegación:</strong> el panel izquierdo agrupa los comprobantes por <strong>rangos semanales de Fecha de Emisión</strong>. El criterio de agrupación se puede cambiar.</li><li><strong>Búsqueda:</strong> caja de texto libre con los botones Buscar y Vaciar.</li><li><strong>Grilla:</strong> Fecha, Comprobante (tipo + punto de venta + número, ej. <code>Spb 0022-00128032</code>), Cuenta, Titular, Nombre, Total y Anulada, más una fila de totales.</li><li><strong>Acciones:</strong> Agregar, Consultar, Elemento, Operaciones, Imprimir, Vista y Filtros.</li><li><strong>Volumen observado:</strong> en la semana 06/08–11/08/2026 hay <strong>12.499 comprobantes</strong> por <strong>$629.206.692,60</strong>, que corresponden a una facturación masiva mensual. Se ven al menos los puntos de venta 0022 y 0028, y los prefijos <code>Spa</code> y <code>Spb</code>.</li></ul><h3 id="detalle-de-un-comprobante-registro-de-facturas-manuales" tabindex="-1">Detalle de un comprobante (&quot;Registro de Facturas Manuales&quot;) <a class="header-anchor" href="#detalle-de-un-comprobante-registro-de-facturas-manuales" aria-label="Permalink to &quot;Detalle de un comprobante (&quot;Registro de Facturas Manuales&quot;)&quot;">​</a></h3><p>Captura: <a href="capturas/18-comprobante-detalle.png">18</a>.</p><ul><li><strong>Cabecera:</strong> Comprobante (ej. &quot;97 - LIQ. DE SERV. B&quot;, PV 0022, Nº 00128032, letra DB), Fecha, Cuenta + domicilio, Titular, Vendedor, Cuota (ej. PR = PREPAGO), Depósito, Período (8 – Agosto 2026), <strong>Deuda Vencida</strong> del titular (en rojo) y check &quot;Registrar Pago&quot;.</li><li><strong>Renglones:</strong> Descripción, Cantidad, Precio Unitario, Impuestos, IVA y Neto. Por ejemplo: <ul><li>ENERGÍA ELÉCTRICA: 18,30 kWh × $270,33.</li><li>Tasas de terceros: Tasa Alumbrado Público, Tasa R. Decreto 2298/00 0,40 %, Tasa RG 27/2015, entre otras.</li></ul></li><li><strong>Totales:</strong> Sub Neto, Descuento %, Neto, Percepciones, IVA, Otros Impuestos y TOTAL. En el ejemplo: Neto $5.441,68, IVA $1.038,88, otros impuestos $519,44 y total $7.000,00.</li><li><strong>Importes y vencimientos:</strong> hasta <strong>4 vencimientos</strong>, cada uno con su fecha y su total con recargo (ej. $7.000,00 y luego $7.001,51 en los siguientes).</li><li><strong>Opción adicional:</strong> &quot;Replicar Comprobante&quot;.</li></ul><p><strong>Implicancias para GoodApps:</strong></p><ul><li>La factura combina el <strong>cargo propio</strong> (energía) con <strong>tasas e impuestos de terceros</strong>: municipales, provinciales y fondos. Cada uno tiene su propia base y alícuota.</li><li>Existe la modalidad <strong>prepaga</strong> de energía.</li><li>El esquema de 4 vencimientos con recargo por interés es parte del modelo del comprobante.</li></ul><h2 id="_5-tablas-del-sistema-parametrizacion" tabindex="-1">5. Tablas del sistema (parametrización) <a class="header-anchor" href="#_5-tablas-del-sistema-parametrizacion" aria-label="Permalink to &quot;5. Tablas del sistema (parametrización)&quot;">​</a></h2><p>Captura: <a href="capturas/20-tablas-sistema-menu.png">20</a>.</p><p>En Configuración, &quot;Tablas del sistema&quot; se organiza en submenús por dominio: Generales, Titulares, Cobranzas, Técnica, Facturación, Gestión de Mora, Telefonía, Viviendas, Sueldos, Tesorería, Contabilidad, Compras, SMS, Actividades y Herramientas.</p><h3 id="tablas-relacionadas-a-facturacion" tabindex="-1">Tablas relacionadas a Facturación <a class="header-anchor" href="#tablas-relacionadas-a-facturacion" aria-label="Permalink to &quot;Tablas relacionadas a Facturación&quot;">​</a></h3><p>Captura: <a href="capturas/21-tablas-facturacion.png">21</a>. Es el núcleo del motor de facturación:</p><ul><li><strong>Comerciales:</strong> Vendedores, Condiciones de Venta para Presupuestos, Tramas de vencimientos de Facturas, Órdenes de impresión en Facturas.</li><li><strong>Fiscales y tarifarias:</strong> Impuestos, Conjuntos de Facturación, Clases de Servicios, Actividades ARCA, Conceptos para Cálculo de Intereses, Grupos de Categorías.</li><li><strong>Catálogo:</strong> Servicios para Facturar, Productos.</li><li><strong>Operativas:</strong> Altas y Bajas Automáticas de Servicios, Conceptos por Cobrar en Operaciones con Titulares, Tipos de Comprobantes, Planes de Cuotas, Cargos Adicionales, <strong>Administración de Cuadros Tarifarios</strong>, Causas de Bloqueo de Comprobantes.</li><li><strong>Fiscal electrónico:</strong> Códigos de Autorización ARCA (CAEA, CESP), Código de Validación Provincial (CVP).</li><li><strong>Especiales:</strong> Configuración de Prepaga, Configurar Facturación Masiva, Opciones de Gas, Grupos de Facturación, Grupos de impresión de gráfico en facturas, Configuración de Conceptos para informe ENACOM, Rendiciones de Viajes, Conceptos a incluir en Facturación a titulares.</li></ul><h3 id="cuadros-tarifarios" tabindex="-1">Cuadros Tarifarios <a class="header-anchor" href="#cuadros-tarifarios" aria-label="Permalink to &quot;Cuadros Tarifarios&quot;">​</a></h3><p>Captura: <a href="capturas/22-cuadros-tarifarios.png">22</a> y <a href="capturas/23-cuadro-tarifario-datos.png">23</a>.</p><ul><li><strong>Listado:</strong> Descripción, Código, Usuario, Vigencia Desde y Hasta. Acciones: Imprimir, Nuevo, Modificar y Salir.</li><li><strong>Versionado:</strong> los cuadros se versionan <strong>por vigencia</strong> y se nombran por mes o por norma. Ejemplos: &quot;ABRIL 2026&quot;, &quot;196/2023 GAS&quot;, &quot;ANTES CAMBIO FODEP 10%&quot;, &quot;ANTES DE RG 129 MARZO&quot;, &quot;ANTES DEL NUEVO DECRETO…&quot;. Es decir, cada resolución del ente regulador genera un cuadro nuevo y el anterior queda cerrado por fecha.</li><li><strong>Detalle:</strong> la pestaña &quot;Datos&quot; con los precios por categoría solo se habilita en modo &quot;Modificar&quot;. <strong>No se abrió</strong>, para no arriesgar cambios. Ese detalle conviene obtenerlo de la base <code>PR_LAG_DEMO</code> o de las DLL decompiladas.</li></ul><h2 id="_6-cobranzas-y-gestion-de-mora-parametrizacion" tabindex="-1">6. Cobranzas y Gestión de Mora (parametrización) <a class="header-anchor" href="#_6-cobranzas-y-gestion-de-mora-parametrizacion" aria-label="Permalink to &quot;6. Cobranzas y Gestión de Mora (parametrización)&quot;">​</a></h2><h3 id="tablas-relacionadas-a-cobranzas" tabindex="-1">Tablas relacionadas a Cobranzas <a class="header-anchor" href="#tablas-relacionadas-a-cobranzas" aria-label="Permalink to &quot;Tablas relacionadas a Cobranzas&quot;">​</a></h3><p>Captura: <a href="capturas/24-tablas-cobranzas.png">24</a>.</p><ul><li><strong>Entes y terceros:</strong> Administración de Entes Recaudadores, Administración de Empresas Tercerizadas.</li><li><strong>Mora:</strong> Administración de Tasas de Mora, Tablas de Índices para Recargo por Mora.</li><li><strong>Intercambio de archivos:</strong> Generar Archivo para Entidad Recaudadora, Importar Archivo de Débitos Automáticos, Exportar archivos de débitos automáticos, Importar Archivo de Morosidad, Importar Archivo de Novedades.</li><li><strong>Caja:</strong> Administración de Descuentos en Caja.</li></ul><p>En la base DEMO hay tres <strong>entes recaudadores</strong> configurados (captura <a href="capturas/25-entes-recaudadores.png">25</a>): DOCUMENTOS A COBRAR, <strong>RED LINK</strong> y <strong>SIRO</strong>.</p><p><strong>Implicancia para GoodApps:</strong> la cobranza externa funciona por <strong>intercambio de archivos batch</strong> con cada ente: se genera un archivo de deuda y después se importa la rendición. Lo mismo vale para débitos automáticos y novedades. Son integraciones críticas para el paralelo.</p><h3 id="tablas-relacionadas-a-gestion-de-mora" tabindex="-1">Tablas relacionadas a Gestión de Mora <a class="header-anchor" href="#tablas-relacionadas-a-gestion-de-mora" aria-label="Permalink to &quot;Tablas relacionadas a Gestión de Mora&quot;">​</a></h3><p>Captura: <a href="capturas/26-tablas-mora.png">26</a>.</p><ul><li><strong>Tablas:</strong> Causas de Baja, Instancias de Mora, Excepciones de Mora.</li><li><strong>Procesos:</strong> Generar Notificaciones, Tratamiento de Notificaciones, Tratamiento de Morosos, Operaciones Especiales.</li></ul><p>Las <strong>instancias</strong> configuradas (captura <a href="capturas/27-instancias-mora.png">27</a>) son tres: 1 CANDIDATOS, 2 PRIMER INSTANCIA DE MORA y 3 SEGUNDA INSTANCIA DE MORA. El flujo sería: un titular es candidato, recibe la notificación de 1ª instancia, luego la de 2ª y finalmente se trata como moroso (corte o baja, con su causa). Las excepciones de mora excluyen cuentas del proceso.</p><h2 id="_7-binarios" tabindex="-1">7. Binarios <a class="header-anchor" href="#_7-binarios" aria-label="Permalink to &quot;7. Binarios&quot;">​</a></h2><p>Los binarios de producción están en la PC demo, en <code>C:\\Procoop\\Sistema\\SISTEMA_PRD\\</code>. Todas las DLL propias tienen fecha 3/8/2026 15:23, igual que la versión 10.4.6.722. Algunas de las que se vieron:</p><table tabindex="0"><thead><tr><th>DLL</th><th>Tamaño</th></tr></thead><tbody><tr><td><code>CapaDatos.dll</code></td><td>3,69 MB</td></tr><tr><td><code>Configuracion.dll</code></td><td>3,75 MB</td></tr><tr><td><code>AVL.dll</code></td><td>41 KB</td></tr><tr><td><code>AxInterop.WMPLib.dll</code></td><td>52 KB</td></tr><tr><td><code>Interop.WMPLib.dll</code></td><td>323 KB</td></tr><tr><td><code>netstandard.dll</code></td><td>96 KB</td></tr><tr><td><code>Recursos\\Tareas.dll</code></td><td>354 bytes</td></tr></tbody></table><p>También hay subcarpetas como <code>Reportes</code>, <code>Reportes_Empresa</code>, <code>Segmentacion</code>, <code>Sincronizaciones</code>, <code>tarifasocial</code>, <code>ENARGAS</code>, <code>Debitos</code>, <code>MailTemplates</code> y <code>CefSharp</code>.</p><p>Se descargó <strong><code>CapaDatos.dll</code></strong> a <a href="binarios/CapaDatos.dll"><code>binarios/CapaDatos.dll</code></a> y se generó su inventario de metadatos en <a href="./binarios/CapaDatos-inventario"><code>binarios/CapaDatos-inventario.md</code></a>.</p><p>Lo que muestra <code>CapaDatos.dll</code>:</p><ul><li><strong>Es el modelo de datos LINQ-to-SQL</strong> de Procoop: 856 tipos, 32.143 métodos y 13.683 campos. Cada clase del namespace <code>CapaDatos</code> es una tabla de la base, con sus relaciones (<code>attach_*</code> / <code>detach_*</code>). Es un mapa casi completo del esquema de <code>PR_LAG_DEMO</code>.</li><li><strong>Tablas clave encontradas:</strong><ul><li>Comprobantes: <code>FACTURAS</code> (relacionada con <code>ITEMSFAC</code>, <code>DEUDAVTA</code>, <code>IT_RECCO</code>, <code>IT_PAGSO</code>, <code>FACTURAS_TERCEROS</code>, <code>TALONFAC</code>, <code>PAGOS360_ITEMS</code>…).</li><li>Servicios: <code>SERVICIO</code> (con <code>CATE_SER</code>, <code>MORATAS</code>, <code>CARGOS_ADICIONALES</code>, <code>IMPUESTOS_X_CAT</code>, <code>FACTOR_CAL</code>, <code>RECLAMOS</code>, <code>FACTIBIL</code>…).</li><li>Tarifas versionadas: <code>CUADROS</code>, con históricos por cuadro (<code>HIS_CATTARIF</code>, <code>HIS_IMPUESTO</code>, <code>HIS_CARGOS_ADICIONALES</code>, <code>HIS_SERVICIO</code>, <code>HIS_PROD_SER</code>, <code>HIS_TAR_ADHE</code>).</li><li>Mora: <code>TABMORA</code> / <code>INDICESMORA</code>, <code>EXC_MORA</code>.</li><li>Fiscal: <code>ACTAFIP</code>, <code>CESPAFIP</code>, <code>EMPAFIP</code>.</li><li>Agrupación de servicios: <code>GRUPOS_FACTURA</code>.</li></ul></li><li><strong>Otros namespaces:</strong> <code>CapaDatos.PMovil</code> (app móvil), <code>CapaDatos.PWeb</code> (portal web / CoopOnline) y <code>CapaDatos.Telemed</code>.</li><li><strong>Motores de datos referenciados:</strong> SQL Server (LINQ to SQL y Entity Framework), MySQL, SQLite y DBF (<code>NDbfReader</code>).</li></ul><h3 id="_7-1-binarios-propios-descargados" tabindex="-1">7.1 Binarios propios descargados <a class="header-anchor" href="#_7-1-binarios-propios-descargados" aria-label="Permalink to &quot;7.1 Binarios propios descargados&quot;">​</a></h3><p>En la PC remota se comprimieron los 70 binarios propios de <code>SISTEMA_PRD</code> (sin DevExpress, System.<em>, Microsoft.</em>, CefSharp, etc.) y se bajaron por Escritorio Remoto a <code>binarios/SISTEMA_PRD/</code> (zip de 29,4 MB). Los inventarios de metadatos están en <a href="./binarios/inventarios/"><code>binarios/inventarios/</code></a>.</p><table tabindex="0"><thead><tr><th>Binario</th><th>Tipos</th><th>Métodos</th><th>SQL embebido</th><th>Rol</th></tr></thead><tbody><tr><td><code>ProcoopNet.exe</code></td><td>57</td><td>644</td><td>3</td><td>Ejecutable principal (shell WinForms)</td></tr><tr><td><code>ReglasNegocio.dll</code></td><td>13.108</td><td>89.737</td><td>597</td><td><strong>Lógica de negocio</strong> de todos los módulos</td></tr><tr><td><code>Configuracion.dll</code></td><td>643</td><td>6.654</td><td>23</td><td>Parametrización y configuración</td></tr><tr><td><code>ProMod_Titulares.dll</code></td><td>307</td><td>2.918</td><td>0</td><td>UI de titulares, cuentas y servicios</td></tr><tr><td><code>ProMod_Facturacion.dll</code></td><td>276</td><td>2.542</td><td>0</td><td>UI de facturación</td></tr><tr><td><code>ProMod_Cobranzas.dll</code></td><td>261</td><td>2.643</td><td>0</td><td>UI de cobranzas</td></tr><tr><td><code>ProMod_Tecnica.dll</code></td><td>142</td><td>1.429</td><td>0</td><td>UI de técnica y reclamos</td></tr><tr><td><code>ProMod_Consumos.dll</code></td><td>102</td><td>848</td><td>0</td><td>UI de lecturas y consumos</td></tr><tr><td><code>ProMod_Tesoreria.dll</code></td><td>65</td><td>691</td><td>0</td><td>UI de tesorería</td></tr><tr><td><code>ProMod_GestionMora.dll</code></td><td>41</td><td>474</td><td>0</td><td>UI de gestión de mora</td></tr><tr><td><code>ProMod_Contabilidad.dll</code></td><td>37</td><td>306</td><td>0</td><td>UI de contabilidad</td></tr><tr><td><code>AutoGestion.exe</code></td><td>71</td><td>597</td><td>0</td><td>Autogestión</td></tr></tbody></table><p>Los <code>ProMod_*</code> son solo pantallas; la lógica está en <strong><code>ReglasNegocio.dll</code></strong>. Namespaces y clases relevantes para GoodApps:</p><ul><li><code>ReglasNegocio.Facturacion</code>: <ul><li><code>clsFacturacionMasiva</code>: proceso mensual (<code>GenerarFacturacion</code>, <code>SimularFacturasConCuadros</code>, <code>ValidarCESP</code>).</li><li><code>clsFacturacionServicio</code>: cálculo de la factura por servicio (<code>FacturarConsumos_MedidoPorTramas</code>, <code>AgregarCuadroTarifario</code>, <code>AgregarItemCargoFijo</code>, <code>AgregarItemFactorPotencia</code>, <code>GC_FacturarDemanda</code>, <code>AddCargosAdicionales</code>, <code>AgregarRedondeo</code>, <code>FacturacionAlumbrado</code>/<code>Cloaca</code>/<code>Pavimento</code>).</li><li><code>clsFacturacionElectronica</code>: AFIP (<code>AutorizaFacturas</code>, <code>AutorizaFacturasCAEA</code>, <code>ConsultarCAE</code>).</li><li>Otras: <code>clsAnulacionFacturas</code>, <code>clsFacturarIntereses</code>, <code>clsRecategorizacion</code>, <code>clsRetroactivos</code>, <code>clsFacturasImpresion</code> (código de barras, Pagos360) y <code>clsEnargas</code> (archivos para ENARGAS).</li></ul></li><li><code>ReglasNegocio.Facturacion.CodigoBarra.Clientes</code>: 91 formatos de código de barras, uno por cooperativa.</li><li><code>ReglasNegocio.Cobranzas.Entidades.*</code>: un namespace por cooperativa cliente (<code>LAG</code> es Laguna Larga), con las interfaces de cobranza propias de cada una.</li><li><code>ReglasNegocio.WSAA</code>, <code>WSFEV1</code>, <code>WSPA13</code>, <code>WSPN3</code>: clientes de los web services de AFIP.</li><li>También: <code>Titulares</code>, <code>Tecnica</code>, <code>Telefonia</code>, <code>Tesoreria</code>, <code>Contabilidad</code>, <code>Sueldos</code>, <code>Stock</code>, <code>Varios.Telemed</code>, <code>Varios.GIS</code> y <code>Varios.CoopOnline</code>.</li></ul><p>Hay copias <code>_old_20260804_071937_*</code> de la versión anterior de varios binarios, que sirven para comparar entre versiones.</p><h3 id="_7-2-codigo-descompilado" tabindex="-1">7.2 Código descompilado <a class="header-anchor" href="#_7-2-codigo-descompilado" aria-label="Permalink to &quot;7.2 Código descompilado&quot;">​</a></h3><p>Con el .NET SDK 8 e <code>ilspycmd</code> 8.2 se descompilaron a proyectos C# en <code>binarios/decompilado/</code>:</p><table tabindex="0"><thead><tr><th>Proyecto</th><th>Archivos <code>.cs</code></th></tr></thead><tbody><tr><td><code>ReglasNegocio</code></td><td>1.339</td></tr><tr><td><code>Configuracion</code></td><td>312</td></tr><tr><td><code>ProcoopNet</code></td><td>17</td></tr></tbody></table><p>Puntos de entrada recomendados para entender la lógica:</p><ul><li><code>ReglasNegocio.Facturacion/clsFacturacionServicio.cs</code> (4.151 líneas). Ejemplo: <code>FacturarTramas</code> reparte el consumo entre los tramos (<code>CATTARIF.CON_MIN</code>/<code>CON_MAX</code>) ajustados por días proporcionales y prorrateo entre cuadros tarifarios.</li><li><code>ReglasNegocio.Facturacion/clsFacturacionMasiva.cs</code>: el proceso mensual.</li><li><code>ReglasNegocio.Facturacion/clsFacturacionElectronica.cs</code>: AFIP.</li><li><code>ReglasNegocio.Facturacion/clsFacturarIntereses.cs</code>: intereses por mora.</li><li><code>ReglasNegocio.Cobranzas/clsGestionMora.cs</code> e <code>clsInformes_Mora.cs</code>.</li></ul><p>Para volver a ejecutarlo: <code>$env:DOTNET_ROLL_FORWARD=&quot;Major&quot;; ilspycmd -p -o &amp;lt;salida&gt; -r binarios/SISTEMA_PRD &amp;lt;dll&gt;</code>. <code>DOTNET_ROLL_FORWARD</code> hace falta porque esa versión de <code>ilspycmd</code> pide .NET 6 y solo está instalado el 8.</p><p>Los binarios y el código descompilado son de terceros. Sirven solo para el análisis y están excluidos de git por <code>.gitignore</code>.</p><h3 id="_7-3-reglas-de-negocio-extraidas-del-codigo" tabindex="-1">7.3 Reglas de negocio extraídas del código <a class="header-anchor" href="#_7-3-reglas-de-negocio-extraidas-del-codigo" aria-label="Permalink to &quot;7.3 Reglas de negocio extraídas del código&quot;">​</a></h3><p>Las reglas que salen del código descompilado están documentadas por dominio en <a href="./reglas-negocio/00-indice"><code>reglas-negocio/</code></a>. Son 10 documentos, cerca de 7.300 líneas en total, y cada regla cita el archivo:línea de origen.</p><h2 id="_8-pendiente-de-relevar" tabindex="-1">8. Pendiente de relevar <a class="header-anchor" href="#_8-pendiente-de-relevar" aria-label="Permalink to &quot;8. Pendiente de relevar&quot;">​</a></h2><ul><li><strong>Cobranza en operación:</strong> Apertura de Caja y Cobranza Local. No se abrieron porque abrir una caja graba datos.</li><li><strong>Detalle de tablas:</strong> el contenido de Cuadros Tarifarios, Impuestos y Conjuntos de Facturación, idealmente vía SQL de solo lectura o las DLL.</li><li><strong>Configurar Facturación Masiva y Telemed:</strong> cómo se dispara el proceso mensual, sin ejecutarlo.</li><li><strong>Contabilidad:</strong> Asientos Automáticos, es decir, cómo impacta la facturación en la contabilidad.</li><li><strong>Procoop WEB y CoopOnline:</strong> la autogestión del socio.</li></ul>`,79)])])}const m=e(s,[["render",i]]);export{g as __pageData,m as default};
